using Alterverse.AI;using Alterverse.CameraSystem;using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Match;using Alterverse.UI;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Prototype
{
public sealed class PrototypeBootstrap:MonoBehaviour
{
[SerializeField]private bool buildOnStart=true;[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<PrototypeBootstrap>()==null)new GameObject("AV_PrototypeBootstrap").AddComponent<PrototypeBootstrap>();}private void Start(){if(buildOnStart)BuildPrototype();}
public void BuildPrototype(){if(GameObject.Find("AV_Player")!=null)return;BuildArena();GameObject player=GameObject.CreatePrimitive(PrimitiveType.Capsule);player.name="AV_Player";player.transform.position=new Vector3(-32,1,-4);Destroy(player.GetComponent<CapsuleCollider>());CharacterController cc=player.AddComponent<CharacterController>();cc.height=2;cc.radius=.5f;HeroId selected=PlayerHeroSelection.Selected;player.AddComponent<HeroIdentity>().Configure(selected);HeroCombatProfile profile=player.AddComponent<HeroCombatProfile>();profile.Configure(selected);player.AddComponent<HeroAbilityKit>().Configure(selected);Health ph=player.AddComponent<Health>();ph.Configure(profile.Health);player.AddComponent<TeamMember>().Initialize(0);player.AddComponent<HeroMotor>();player.AddComponent<HeroRespawn>();player.AddComponent<BasicAttack>();player.AddComponent<PlayerHeroAbilities>();SetColor(player,Color.Lerp(StylizedArtDirection.HeroAccent(selected),StylizedArtDirection.ZeroDark,.45f));player.AddComponent<CombatFeedback>();player.AddComponent<StylizedHeroVisual>();SpawnHealingZone zeroZone=GameObject.Find("AV_ZeroSpawnZone")?.GetComponent<SpawnHealingZone>();if(zeroZone!=null){zeroZone.InitializeTeam(0);zeroZone.Initialize(ph);}SpawnHealingZone lumenZone=GameObject.Find("AV_LumenSpawnZone")?.GetComponent<SpawnHealingZone>();if(lumenZone!=null)lumenZone.InitializeTeam(1);UnityEngine.Camera cam=UnityEngine.Camera.main;if(cam==null){GameObject c=new("Main Camera");c.tag="MainCamera";cam=c.AddComponent<UnityEngine.Camera>();}cam.backgroundColor=StylizedArtDirection.Ink;MobaCamera mc=cam.GetComponent<MobaCamera>()??cam.gameObject.AddComponent<MobaCamera>();mc.SetTarget(player.transform);new GameObject("AV_HUD").AddComponent<PrototypeHUD>().Initialize(ph,null,null);new GameObject("DF_TargetIndicator").AddComponent<TargetIndicatorHUD>();new GameObject("AV_LaneWaveSpawner").AddComponent<LaneWaveSpawner>();new GameObject("AV_5v5Roster").AddComponent<FiveVsFiveTestRoster>();new GameObject("AV_DimensionsFront").AddComponent<DimensionsFront>();new GameObject("AV_DimensionsFrontCombatBridge").AddComponent<DimensionsFrontCombatBridge>();new GameObject("AV_DimensionsFrontVisual").AddComponent<DimensionsFrontVisual>();new GameObject("AV_DimensionsFrontHUD").AddComponent<DimensionsFrontHUD>();new GameObject("DF_DimensionPlanetDirector").AddComponent<DimensionPlanetDirector>();new GameObject("DF_PlanetHUD").AddComponent<PlanetHUD>();new GameObject("AV_MatchTelemetry").AddComponent<MatchTelemetry>();new GameObject("AV_MatchScoreboard").AddComponent<MatchScoreboard>();new GameObject("AV_MatchOpening").AddComponent<MatchOpening>();}
private static void BuildArena(){Color lane=Color.Lerp(StylizedArtDirection.ZeroMid,StylizedArtDirection.LumenMid,.5f);CreateGround("AV_DimensionZeroGround",new Vector3(-21,-.12f,0),new Vector3(42,.2f,72),StylizedArtDirection.ZeroDark);CreateGround("AV_LumenGround",new Vector3(21,-.12f,0),new Vector3(42,.2f,72),StylizedArtDirection.LumenDark);CreateLane("AV_TopLane",16,lane);CreateLane("AV_MidLane",0,lane);CreateLane("AV_BotLane",-16,lane);CreateVisualBlock("AV_ZeroBasePad",new Vector3(-36,.04f,0),new Vector3(8,.05f,22),StylizedArtDirection.ZeroMid,Vector3.zero);CreateVisualBlock("AV_LumenBasePad",new Vector3(36,.04f,0),new Vector3(8,.05f,22),StylizedArtDirection.LumenMid,Vector3.zero);CreateBaseCore(new Vector3(-36,1.15f,0),StylizedArtDirection.ZeroEnergy,"AV_ZeroRealityCore");CreateBaseCore(new Vector3(36,1.15f,0),StylizedArtDirection.LumenEnergy,"AV_LumenRealityCore");CreateSpawnZone(new Vector3(-34,.07f,-4),StylizedArtDirection.ZeroEnergy,"AV_ZeroSpawnZone");CreateSpawnZone(new Vector3(34,.07f,4),StylizedArtDirection.LumenEnergy,"AV_LumenSpawnZone");CreateTowers();for(int i=-15;i<=15;i++){float z=i*2.25f,x=Mathf.Sin(i*1.73f)*.65f;CreateVisualBlock("AV_RealityScar",new Vector3(x,.055f,z),new Vector3(.34f,.045f,1.85f),StylizedArtDirection.ZeroEnergy,new Vector3(0,Mathf.Sin(i)*13,0));}for(int z=-28;z<=28;z+=8){CreateObelisk(new Vector3(-38,1.25f,z),StylizedArtDirection.ZeroMid,false);CreateObelisk(new Vector3(38,1.25f,z),StylizedArtDirection.LumenMid,true);}for(int z=-24;z<=24;z+=12){CreateCrystal(new Vector3(-13,.65f,z),StylizedArtDirection.ZeroEnergy);CreateCrystal(new Vector3(13,.65f,z),StylizedArtDirection.LumenEnergy);}CreateObjectiveZone(new Vector3(0,.07f,27),StylizedArtDirection.LumenEnergy,"DF_NorthPlanetArena");CreateObjectiveZone(new Vector3(0,.07f,-27),StylizedArtDirection.ZeroEnergy,"DF_SouthPlanetArena");CreateRiftCore();new GameObject("DF_StylizedArenaOverlay").AddComponent<StylizedArenaOverlay>();new GameObject("DF_ArenaAtmosphere").AddComponent<ArenaAtmosphere>();new GameObject("DF_DimensionArenaArchitecture").AddComponent<DimensionArenaArchitecture>();new GameObject("DF_RealityCollisionLandmarks").AddComponent<RealityCollisionLandmarks>();}
private static void CreateSpawnZone(Vector3 p,Color c,string n){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=new Vector3(4.5f,.025f,4.5f);DisableCollider(g);SetColor(g,c);g.AddComponent<SpawnHealingZone>();}private static void CreateLane(string n,float z,Color c){CreateVisualBlock(n,new Vector3(0,.035f,z),new Vector3(72,.045f,2.4f),c,Vector3.zero);CreateVisualBlock(n+"_ZeroConnector",new Vector3(-30,.04f,z*.58f),new Vector3(15,.045f,1.6f),c,new Vector3(0,z>0?-22:z<0?22:0,0));CreateVisualBlock(n+"_LumenConnector",new Vector3(30,.04f,z*.58f),new Vector3(15,.045f,1.6f),c,new Vector3(0,z>0?22:z<0?-22:0,0));}private static void CreateTowers(){float[] lanes={16,0,-16};foreach(float z in lanes){CreateTower(new Vector3(-25,1.25f,z),0,StylizedArtDirection.ZeroMid,"AV_ZeroTower");CreateTower(new Vector3(25,1.25f,z),1,StylizedArtDirection.LumenMid,"AV_LumenTower");}}private static void CreateTower(Vector3 p,int team,Color c,string n){GameObject t=GameObject.CreatePrimitive(PrimitiveType.Cylinder);t.name=n;t.transform.position=p;t.transform.localScale=new Vector3(.9f,1.25f,.9f);SetColor(t,c);Health h=t.AddComponent<Health>();h.Configure(260,true);t.AddComponent<LaneTower>().Initialize(team);CreateVisualCylinder(n+"_Base",new Vector3(p.x,.08f,p.z),new Vector3(1.25f,.03f,1.25f),c);}private static void CreateObjectiveZone(Vector3 p,Color c,string n){CreateVisualCylinder(n,p,new Vector3(2.5f,.025f,2.5f),c);for(int i=0;i<4;i++){float a=i*90*Mathf.Deg2Rad;CreateShard(p+new Vector3(Mathf.Cos(a)*2,.55f,Mathf.Sin(a)*2),c,.4f,true);}}private static void CreateBaseCore(Vector3 p,Color c,string n){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=new Vector3(1.4f,1.15f,1.4f);DisableCollider(g);SetColor(g,c);}private static void CreateRiftCore(){CreateVisualCylinder("AV_RiftOuter",new Vector3(0,.075f,0),new Vector3(3.25f,.035f,3.25f),StylizedArtDirection.Ink);CreateVisualCylinder("AV_RiftInner",new Vector3(0,.095f,0),new Vector3(2.35f,.045f,2.35f),StylizedArtDirection.ZeroEnergy);CreateVisualCylinder("AV_RiftEye",new Vector3(0,.115f,0),new Vector3(1.15f,.05f,1.15f),StylizedArtDirection.LumenEnergy);GameObject core=GameObject.CreatePrimitive(PrimitiveType.Cube);core.name="AV_RiftCore";core.transform.position=new Vector3(0,1.45f,0);core.transform.localScale=Vector3.one*.72f;core.transform.rotation=Quaternion.Euler(25,45,20);DisableCollider(core);SetColor(core,Color.white);core.AddComponent<RiftCoreVisual>();}private static void CreateGround(string n,Vector3 p,Vector3 s,Color c){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;SetColor(g,c);}private static void CreateObelisk(Vector3 p,Color c,bool future){GameObject o=GameObject.CreatePrimitive(future?PrimitiveType.Cube:PrimitiveType.Cylinder);o.name=future?"AV_LumenStructure":"AV_ZeroObelisk";o.transform.position=p;o.transform.localScale=future?new Vector3(.65f,2.3f,.65f):new Vector3(.8f,1.8f,.8f);o.transform.rotation=Quaternion.Euler(0,future?45:0,future?8:0);DisableCollider(o);SetColor(o,c);}private static void CreateCrystal(Vector3 p,Color c){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="AV_RealityCrystal";g.transform.position=p;g.transform.localScale=new Vector3(.38f,1.25f,.38f);g.transform.rotation=Quaternion.Euler(18,45,18);DisableCollider(g);SetColor(g,c);g.AddComponent<MapAmbientVisual>();}private static void CreateShard(Vector3 p,Color c,float size,bool animated){GameObject s=GameObject.CreatePrimitive(PrimitiveType.Cube);s.name="AV_RiftShard";s.transform.position=p;s.transform.localScale=new Vector3(size*.35f,size,size*.35f);s.transform.rotation=Quaternion.Euler(20,45,25);DisableCollider(s);SetColor(s,c);if(animated)s.AddComponent<MapAmbientVisual>();}private static void CreateVisualCylinder(string n,Vector3 p,Vector3 s,Color c){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=n;g.transform.position=p;g.transform.localScale=s;DisableCollider(g);SetColor(g,c);}private static void CreateVisualBlock(string n,Vector3 p,Vector3 s,Color c,Vector3 r){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;g.transform.rotation=Quaternion.Euler(r);DisableCollider(g);SetColor(g,c);}private static void DisableCollider(GameObject g){Collider c=g.GetComponent<Collider>();if(c!=null)c.enabled=false;}private static void SetColor(GameObject g,Color c){Renderer r=g.GetComponent<Renderer>();if(r!=null)r.material.color=c;}
}}
